package com.example.rokidkeyboardbridge;
public class RestLegRelaxTest {public static int n;static void ok(boolean v,String m){n++;if(!v)throw new AssertionError(m);}public static void main(String[] args){for(String q:new String[]{"ちょっと足を開かせて","足を少し開いて","脚を少し離して","寝たまま脚を少し開いて","ロキ、ちょっと足を開かせてください"}){ok(RestLegRelaxIntent.request(q),"bounded direct command "+q);EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user(q,10000);ok(p.correctedRest()&&p.restMotion(10000)==16&&p.posture()==0,"actual relaxed leg rest selected");p.answer(RestLegRelaxIntent.REPLY,FullBodyPoseCatalog.Kind.NEUTRAL,11000);ok(p.restMotion(11000)==16,"spoken reply preserves body");p.user("眠そうな顔にして",12000);ok(p.restMotion(12000)==16&&p.restFace()==10,"face preserves leg spacing");p.user("身じろぎを止めて",13000);ok(p.restMotion(13000)==16&&!p.moving(13000),"stop leaves pose stable");p.user("立って",14000);ok(!p.correctedRest(),"explicit exit");}for(String q:new String[]{"足を少し開かないで","足を少し開いてほしくない","足を大きく開いて","開脚して","彼女が足を少し開いている","足を少し開いてという例文","足を少し開いて？"})ok(!RestLegRelaxIntent.request(q),"negation/quote/question/unrelated motion excluded");ok(ComfortPoseGeometry.ASSETS[8].contains("v684"),"separate new atlas retains original pose");for(int face=0;face<4;face++){int[] c=ComfortPoseGeometry.crop(8,face);ok(c[0]>=0&&c[1]>=0&&c[0]+c[2]<=1024&&c[1]+c[3]<=1536,"face crop valid");}for(int variant=0;variant<20;variant++)ok(NaturalPosePolicy.alternative(0,variant)!=16,"new leg gap not added to unrequested automatic rotation");System.out.println("PASS "+n+" small leg-rest intent, body continuity and selection checks");}}
